add.source:
/* add.c — cùng bài toán với chương trình "add" của CPU đồ chơi (Load X · Add Y · Store Z) */
int x = 5, y = 7;   /* biến có giá trị đầu  → đoạn .data */
int z;              /* biến chưa gán        → đoạn .bss  */

int main(void) {
    z = x + y;
    return z;       /* chạy xong: echo $?  → 12 */
}

sum.source:
/* sum.c — tổng 1..n, cùng bài toán với chương trình "sum" của CPU đồ chơi */
int sum_to(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++)
        sum += i;
    return sum;
}

int main(void) {
    return sum_to(5);   /* echo $?  → 15 */
}

max.source:
/* max.c — số lớn nhất của mảng, cùng bài toán với chương trình "max" của CPU đồ chơi */
int arr[] = {3, 9, 4, 7};

int max_of(const int *a, int n) {
    int m = a[0];
    for (int i = 1; i < n; i++)
        if (a[i] > m)
            m = a[i];
    return m;
}

int main(void) {
    return max_of(arr, 4);   /* echo $?  → 9 */
}
